        if not fg:
            continue
        # A single contiguous foreground segment with a background tail is the
        # trace to continue; fragmented rows and lines reaching the edge stay.
        left, right = min(fg), max(fg)
        if len(fg) == right - left + 1 and right < len(row) - 1:
            for c in range(right + 1, len(row)):
                out[r][c] = 1
    return out

