def transform(grid):
    # The background is the majority corner color. Mark the trailing
    # background suffix when its preceding terminal run is at least as long
    # as the suffix.
    from collections import Counter
    corners = [grid[0][0], grid[0][-1], grid[-1][0], grid[-1][-1]]
    bg = Counter(corners).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        end = len(row)
        while end > 0 and row[end - 1] == bg:
            end -= 1
        gap = len(row) - end
        if not gap or end == 0:
            continue
        color = row[end - 1]
        start = end - 1
        while start > 0 and row[start - 1] == color:
            start -= 1
        if end - start >= gap:
            for c in range(end, len(row)):
                out[r][c] = 1
    return out
